"""
Sphinx extension for easier documenting of protocols in other libraries.

In order to use autodocumenters provided in this module, add
`"taf.internal.contracts.sphinx_ext"` string to the list of extensions in your
documentation's `conf.py` file.
"""

# TODO: Add this to the documentation

from __future__ import annotations

from inspect import isclass
from types import ModuleType
from typing import Any

from docutils.statemachine import StringList
from sphinx.application import Sphinx
from sphinx.errors import SphinxError
from sphinx.ext.autodoc import ClassDocumenter, ModuleDocumenter

from . import (
    find_all_providers,
    get_contract_by_name,
)
from .contracts import get_provided_contracts


class MissingContract(SphinxError):
    """Raised if ..autocontracts:: directive is missing :contract: option."""


class UnknownContract(SphinxError):
    """Raised if ..autocontracts:: directive is set to an unknown :contract:.

    See `get_contract_by_name(name)`. This exception will get raised for any
    `:contract: name` for which that function returns `None`.
    """


# TODO: This should be done via sphinx.ext.intersphinx, but it is not
# working on our RTD currently.
CONTRACTS_URL = (
    "https://taf-internal-contracts.docs.taf.ute.nsn-rdnet.net/en/latest/"
    "api/reference.html#taf.internal.contracts.{contract_name}"
)


ANCHOR_PREFIX = "auto-contract-"


def anchor_for_contract_table(contract_name: str) -> str:
    return f".. _{ANCHOR_PREFIX}{contract_name}:"


def reference_contract_table(link_text: str, contract_name: str) -> str:
    return f":ref:`{link_text}<{ANCHOR_PREFIX}{contract_name}>`"


class AutoContracts(ModuleDocumenter):
    """Writes a table with all contract providing classes from a specified module.

    Example usage::

        .. autocontracts:: very.important.module
           :contract: Ssh

           This is some content that will be written above the table.
    """

    objtype = "contracts"
    directivetype = ModuleDocumenter.objtype
    option_spec = {
        "contract": str,
    }

    TABLE_TITLE = (
        f"✨ Classes that satifsfy `{{contract_name}} <{CONTRACTS_URL}>`_ contract ✨"
    )

    @classmethod
    def can_document_member(
        cls, member: Any, membername: str, isattr: bool, parent: Any
    ) -> bool:
        # Do not attempt do document members with this class
        return False

    def add_directive_header(self, sig: str) -> None:
        super().add_directive_header(sig)
        self.add_line("   :noindex:", self.get_sourcename())

    def add_content(
        self,
        more_content: StringList | None,
    ) -> None:
        contract_name = self.options.get("contract", None)
        if contract_name is None:
            raise MissingContract(
                "Missing :contract: option in ..autocontract directive."
            )

        contract = get_contract_by_name(contract_name)
        if contract is None:
            raise UnknownContract(
                f"Unrecognized contract in ..autocontract directive: {contract_name!r}."
            )

        module: ModuleType = self.object
        contract_providing_classes = find_all_providers(module, contract)

        source_name = self.get_sourcename()

        # Add anchor for use by AutoContractProvider
        self.add_line(anchor_for_contract_table(contract_name), source_name)

        # Section title
        self.add_line(f"{contract_name}", source_name)
        self.add_line(f"{'-' * len(contract_name)}", source_name)

        # Content
        super().add_content(more_content)
        self.add_line("", source_name)

        # Table with the title
        self.add_line(
            f".. list-table:: {self.TABLE_TITLE.format(contract_name=contract_name)}",
            source_name,
        )

        # Options
        self.add_line("   :widths: 25", source_name)
        self.add_line("   :header-rows: 1", source_name)
        self.add_line("", source_name)

        # Header
        self.add_line("   * - Class", source_name)

        for klass in sorted(
            contract_providing_classes.values(), key=lambda m: m.__name__
        ):
            self.add_line(
                f"   * - :py:class:`{module.__name__}.{klass.__name__}`", source_name
            )


class AutoContractProvider(ClassDocumenter):
    """Writes a table with all contracts supported by the documented class.

    This documenter is used automatically when auto-documenting a module.
    """

    objtype = "contract_provider_class"
    directivetype = ClassDocumenter.objtype
    priority = 99 + ClassDocumenter.priority

    TABLE_TITLE = "✨ Provides data in the following contracts ✨"

    @classmethod
    def can_document_member(
        cls, member: Any, membername: str, isattr: bool, parent: Any
    ) -> bool:
        return isclass(member) and any(
            attr.startswith("__taf_contract_") and attr.endswith("__")
            for attr in dir(member)
        )

    def add_content(
        self,
        more_content: StringList | None,
    ) -> None:
        super().add_content(more_content)

        klass = self.object
        source_name = self.get_sourcename()

        # Title
        self.add_line(
            f".. list-table:: {self.TABLE_TITLE}",
            source_name,
        )

        # Options
        self.add_line("   :header-rows: 1", source_name)
        self.add_line("", source_name)

        # Header
        self.add_line("   * - Contract", source_name)
        self.add_line("     - Usage", source_name)

        for contract in get_provided_contracts(klass):
            contract_name = contract.__name__

            url = CONTRACTS_URL.format(contract_name=contract_name)
            link = f"`(contract information) <{url}>`_"
            self.add_line(f"   * - {contract_name} {link}", source_name)

            more_info_ref = reference_contract_table("Usage information", contract_name)
            self.add_line(f"     - {more_info_ref}", source_name)


def setup(app: Sphinx):
    app.setup_extension("sphinx.ext.autodoc")
    app.add_autodocumenter(AutoContracts)
    app.add_autodocumenter(AutoContractProvider)
    return {
        "version": 3,
        "parallel_read_safe": True,
    }
